-- Tags: long
-- long: many statements; over the time limit of the flaky check under the thread fuzzer.

-- The writers through merges and mutations: horizontal and vertical merges in small blocks, mutations that rewrite the
-- column and mutations that hardlink it, lightweight deletes and updates, indexes and columns materialized from a SHARED
-- path, rename and drop, FINAL, mixed part types, a materialized view and a projection holding the column. Compared
-- with a Memory table of the type without SHARED; each line prints an equality flag.

DROP TABLE IF EXISTS mem; CREATE TABLE mem (x UInt64, y UInt64, json JSON(a UInt64, b String, c Array(UInt8))) ENGINE = Memory; INSERT INTO mem SELECT number, number, concat('{"a":', toString(number * 10), ',"b":"', repeat('x', number % 7), '","c":', toString(range(number % 4)), if(number % 2 = 0, concat(',"d":', toString(number)), ''), '}') FROM numbers(40);
SELECT '-- w: merges, mutations rewriting and hardlinking the column, indexes and columns from a SHARED path, deletes, rename, drop';
DROP TABLE IF EXISTS t_w; CREATE TABLE t_w (x UInt64, y UInt64, json JSON(SHARED a UInt64, SHARED b String, SHARED c Array(UInt8))) ENGINE = MergeTree ORDER BY x SETTINGS min_bytes_for_wide_part = 0, min_rows_for_wide_part = 0, index_granularity = 4, min_compress_block_size = 1, merge_max_block_size = 5;
INSERT INTO t_w SELECT number, number, concat('{"a":', toString(number * 10), ',"b":"', repeat('x', number % 7), '","c":', toString(range(number % 4)), if(number % 2 = 0, concat(',"d":', toString(number)), ''), '}') FROM numbers(20); INSERT INTO t_w SELECT number, number, concat('{"a":', toString(number * 10), ',"b":"', repeat('x', number % 7), '","c":', toString(range(number % 4)), if(number % 2 = 0, concat(',"d":', toString(number)), ''), '}') FROM numbers(20, 20);
SELECT 't_w [json]', (SELECT arraySort(groupArray((x, toString(json)))) FROM t_w  SETTINGS max_threads = 1) = (SELECT arraySort(groupArray((x, toString(json)))) FROM mem );
SELECT 't_w [(json.a, json.c.size0)]', (SELECT arraySort(groupArray((x, toString((json.a, json.c.size0))))) FROM t_w  SETTINGS max_threads = 1) = (SELECT arraySort(groupArray((x, toString((json.a, json.c.size0))))) FROM mem );
OPTIMIZE TABLE t_w FINAL;
SELECT 't_w parts', count(), sum(rows) FROM system.parts WHERE database = currentDatabase() AND table = 't_w' AND active;
SELECT 't_w [json]', (SELECT arraySort(groupArray((x, toString(json)))) FROM t_w  SETTINGS max_threads = 1) = (SELECT arraySort(groupArray((x, toString(json)))) FROM mem );
SELECT 't_w [(json.b, json)]', (SELECT arraySort(groupArray((x, toString((json.b, json))))) FROM t_w  SETTINGS max_threads = 1) = (SELECT arraySort(groupArray((x, toString((json.b, json))))) FROM mem );
CHECK TABLE t_w SETTINGS check_query_single_value_result = 1;
ALTER TABLE t_w UPDATE json = json WHERE 1 SETTINGS mutations_sync = 2;
SELECT 't_w [json]', (SELECT arraySort(groupArray((x, toString(json)))) FROM t_w  SETTINGS max_threads = 1) = (SELECT arraySort(groupArray((x, toString(json)))) FROM mem );
SELECT 't_w [(json.a, json.c.size0, json.d)]', (SELECT arraySort(groupArray((x, toString((json.a, json.c.size0, json.d))))) FROM t_w  SETTINGS max_threads = 1) = (SELECT arraySort(groupArray((x, toString((json.a, json.c.size0, json.d))))) FROM mem );
CHECK TABLE t_w SETTINGS check_query_single_value_result = 1;
ALTER TABLE t_w UPDATE y = y + 1000 WHERE 1 SETTINGS mutations_sync = 2;
ALTER TABLE mem UPDATE y = y + 1000 WHERE 1;
SELECT 't_w [(y, json)]', (SELECT arraySort(groupArray((x, toString((y, json))))) FROM t_w  SETTINGS max_threads = 1) = (SELECT arraySort(groupArray((x, toString((y, json))))) FROM mem );
SELECT 't_w [json.b]', (SELECT arraySort(groupArray((x, toString(json.b)))) FROM t_w  SETTINGS max_threads = 1) = (SELECT arraySort(groupArray((x, toString(json.b)))) FROM mem );
ALTER TABLE t_w ADD INDEX ia json.a TYPE minmax GRANULARITY 1; ALTER TABLE t_w MATERIALIZE INDEX ia SETTINGS mutations_sync = 2;
SELECT 't_w index', count() FROM t_w WHERE json.a = 130;
SELECT 't_w [json]', (SELECT arraySort(groupArray((x, toString(json)))) FROM t_w  SETTINGS max_threads = 1) = (SELECT arraySort(groupArray((x, toString(json)))) FROM mem );
ALTER TABLE t_w ADD COLUMN z UInt64 DEFAULT json.a + 100; ALTER TABLE t_w MATERIALIZE COLUMN z SETTINGS mutations_sync = 2;
SELECT 't_w materialized column', sum(z) = (SELECT sum(json.a + 100) FROM mem) FROM t_w;
ALTER TABLE t_w MODIFY COLUMN y String SETTINGS mutations_sync = 2;
SELECT 't_w [(json, json.a)]', (SELECT arraySort(groupArray((x, toString((json, json.a))))) FROM t_w  SETTINGS max_threads = 1) = (SELECT arraySort(groupArray((x, toString((json, json.a))))) FROM mem );
CHECK TABLE t_w SETTINGS check_query_single_value_result = 1;
DELETE FROM t_w WHERE json.a < 50;
SELECT 't_w [json] WHERE json.a >= 50', (SELECT arraySort(groupArray((x, toString(json)))) FROM t_w WHERE json.a >= 50 SETTINGS max_threads = 1) = (SELECT arraySort(groupArray((x, toString(json)))) FROM mem WHERE json.a >= 50);
SELECT 't_w [(json.c.size0, json.b)] WHERE json.a >= 50', (SELECT arraySort(groupArray((x, toString((json.c.size0, json.b))))) FROM t_w WHERE json.a >= 50 SETTINGS max_threads = 1) = (SELECT arraySort(groupArray((x, toString((json.c.size0, json.b))))) FROM mem WHERE json.a >= 50);
SELECT 't_w after lightweight delete', count() FROM t_w;
ALTER TABLE t_w DELETE WHERE json.b = '' SETTINGS mutations_sync = 2;
SELECT 't_w [json] WHERE json.a >= 50 AND json.b != ''', (SELECT arraySort(groupArray((x, toString(json)))) FROM t_w WHERE json.a >= 50 AND json.b != '' SETTINGS max_threads = 1) = (SELECT arraySort(groupArray((x, toString(json)))) FROM mem WHERE json.a >= 50 AND json.b != '');
SELECT 't_w [(json.a, json)] WHERE json.a >= 50 AND json.b != ''', (SELECT arraySort(groupArray((x, toString((json.a, json))))) FROM t_w WHERE json.a >= 50 AND json.b != '' SETTINGS max_threads = 1) = (SELECT arraySort(groupArray((x, toString((json.a, json))))) FROM mem WHERE json.a >= 50 AND json.b != '');
SELECT 't_w after delete', count() FROM t_w;
ALTER TABLE t_w ADD INDEX ti json.b TYPE text(tokenizer = 'splitByNonAlpha') GRANULARITY 1; ALTER TABLE t_w MATERIALIZE INDEX ti SETTINGS mutations_sync = 2;
OPTIMIZE TABLE t_w FINAL;
SELECT 't_w text index', count() FROM t_w WHERE hasToken(json.b, 'xxx');
SELECT 't_w [json] WHERE json.a >= 50 AND json.b != ''', (SELECT arraySort(groupArray((x, toString(json)))) FROM t_w WHERE json.a >= 50 AND json.b != '' SETTINGS max_threads = 1) = (SELECT arraySort(groupArray((x, toString(json)))) FROM mem WHERE json.a >= 50 AND json.b != '');
ALTER TABLE t_w DROP INDEX ia, DROP INDEX ti, MODIFY COLUMN z REMOVE DEFAULT;
ALTER TABLE t_w RENAME COLUMN json TO json_r;
SELECT 't_w renamed', (SELECT arraySort(groupArray((x, toString(json_r)))) FROM t_w SETTINGS max_threads = 1) = (SELECT arraySort(groupArray((x, toString(json)))) FROM mem WHERE json.a >= 50 AND json.b != ''), sum(json_r.a) FROM t_w;
CHECK TABLE t_w SETTINGS check_query_single_value_result = 1;
ALTER TABLE t_w DROP COLUMN json_r;
SELECT 't_w dropped', count(), sum(z) FROM t_w;
CHECK TABLE t_w SETTINGS check_query_single_value_result = 1;
DROP TABLE t_w;
ALTER TABLE mem UPDATE y = y - 1000 WHERE 1;
