SELECT '-- vertical merges, with the SHARED path in the sorting key';
DROP TABLE IF EXISTS v_w; CREATE TABLE v_w (x UInt64, y UInt64, json JSON(SHARED a UInt64, SHARED b String, SHARED c Array(UInt8))) ENGINE = MergeTree ORDER BY (json.a, x) SETTINGS min_bytes_for_wide_part = 0, min_rows_for_wide_part = 0, index_granularity = 4, min_compress_block_size = 1, merge_max_block_size = 5, vertical_merge_algorithm_min_rows_to_activate = 1, vertical_merge_algorithm_min_columns_to_activate = 1, allow_vertical_merges_from_compact_to_wide_parts = 1;
INSERT INTO v_w SELECT number, number, concat('{"a":', toString(number * 10), ',"b":"', repeat('x', number % 7), '","c":', toString(range(number % 4)), if(number % 2 = 0, concat(',"d":', toString(number)), ''), '}') FROM numbers(20); INSERT INTO v_w SELECT number, number, concat('{"a":', toString(number * 10), ',"b":"', repeat('x', number % 7), '","c":', toString(range(number % 4)), if(number % 2 = 0, concat(',"d":', toString(number)), ''), '}') FROM numbers(20, 20);
OPTIMIZE TABLE v_w FINAL;
SELECT 'v_w parts', count(), sum(rows), any(part_type) FROM system.parts WHERE database = currentDatabase() AND table = 'v_w' AND active;
SELECT 'v_w [json]', (SELECT arraySort(groupArray((x, toString(json)))) FROM v_w  SETTINGS max_threads = 1) = (SELECT arraySort(groupArray((x, toString(json)))) FROM mem );
SELECT 'v_w [(json.a, json.b)]', (SELECT arraySort(groupArray((x, toString((json.a, json.b))))) FROM v_w  SETTINGS max_threads = 1) = (SELECT arraySort(groupArray((x, toString((json.a, json.b))))) FROM mem );
SELECT 'v_w [(json.c.size0, json)] WHERE json.a >= 100 AND json.a < 300', (SELECT arraySort(groupArray((x, toString((json.c.size0, json))))) FROM v_w WHERE json.a >= 100 AND json.a < 300 SETTINGS max_threads = 1) = (SELECT arraySort(groupArray((x, toString((json.c.size0, json))))) FROM mem WHERE json.a >= 100 AND json.a < 300);
SELECT 'v_w order', (SELECT groupArray(json.a) FROM (SELECT json.a FROM v_w LIMIT 6 SETTINGS max_threads = 1)) = (SELECT groupArray(a) FROM (SELECT json.a AS a FROM mem ORDER BY a, x LIMIT 6));
CHECK TABLE v_w SETTINGS check_query_single_value_result = 1;
DROP TABLE v_w;
DROP TABLE IF EXISTS v_cm; CREATE TABLE v_cm (x UInt64, y UInt64, json JSON(SHARED a UInt64, SHARED b String, SHARED c Array(UInt8))) ENGINE = MergeTree ORDER BY (json.a, x) SETTINGS min_bytes_for_wide_part = 1000000000, min_rows_for_wide_part = 1000000000, index_granularity = 4, write_marks_for_substreams_in_compact_parts = 1, merge_max_block_size = 5, vertical_merge_algorithm_min_rows_to_activate = 1, vertical_merge_algorithm_min_columns_to_activate = 1, allow_vertical_merges_from_compact_to_wide_parts = 1;
