DROP TABLE e_cn;
SELECT '-- ALTER MODIFY COLUMN from String to JSON(SHARED d Dynamic) in merge blocks of different Dynamic structures';
DROP TABLE IF EXISTS c_w; CREATE TABLE c_w (x UInt64, s String) ENGINE = MergeTree ORDER BY x SETTINGS min_bytes_for_wide_part = 0, min_rows_for_wide_part = 0, index_granularity = 4, min_compress_block_size = 1, merge_max_block_size = 4;
INSERT INTO c_w SELECT number, concat('{"d":', multiIf(number % 4 = 0, toString(number), number % 4 = 1, concat('"s', toString(number), '"'), number % 4 = 2, concat('[', toString(number), ']'), 'true'), ',"e":', toString(number), '}') FROM numbers(24);
ALTER TABLE c_w MODIFY COLUMN s JSON(SHARED d Dynamic) SETTINGS mutations_sync = 2;
SELECT 'c_w', count(), sum(s.d.:Int64), sum(length(s.d.String)), sum(length(s.d.`Array(Nullable(Int64))`)), sum(s.d.Bool), sum(s.e.:Int64), (SELECT groupArray(toString(s.d)) FROM (SELECT s FROM c_w ORDER BY x LIMIT 4)) FROM c_w SETTINGS max_threads = 1;
SELECT 'c_w whole', (SELECT arraySort(groupArray((x, toString(s)))) FROM c_w SETTINGS max_threads = 1, max_block_size = 5) = (SELECT arraySort(groupArray((number, concat('{"d":', multiIf(number % 4 = 0, toString(number), number % 4 = 1, concat('"s', toString(number), '"'), number % 4 = 2, concat('[', toString(number), ']'), 'true'), ',"e":', toString(number), '}')))) FROM numbers(24));
CHECK TABLE c_w SETTINGS check_query_single_value_result = 1;
DROP TABLE c_w;
DROP TABLE IF EXISTS c_cn; CREATE TABLE c_cn (x UInt64, s String) ENGINE = MergeTree ORDER BY x SETTINGS min_bytes_for_wide_part = 1000000000, min_rows_for_wide_part = 1000000000, index_granularity = 4, write_marks_for_substreams_in_compact_parts = 0, merge_max_block_size = 4;
INSERT INTO c_cn SELECT number, concat('{"d":', multiIf(number % 4 = 0, toString(number), number % 4 = 1, concat('"s', toString(number), '"'), number % 4 = 2, concat('[', toString(number), ']'), 'true'), ',"e":', toString(number), '}') FROM numbers(24);
ALTER TABLE c_cn MODIFY COLUMN s JSON(SHARED d Dynamic) SETTINGS mutations_sync = 2;
SELECT 'c_cn', count(), sum(s.d.:Int64), sum(length(s.d.String)), sum(length(s.d.`Array(Nullable(Int64))`)), sum(s.d.Bool), sum(s.e.:Int64), (SELECT groupArray(toString(s.d)) FROM (SELECT s FROM c_cn ORDER BY x LIMIT 4)) FROM c_cn SETTINGS max_threads = 1;
SELECT 'c_cn whole', (SELECT arraySort(groupArray((x, toString(s)))) FROM c_cn SETTINGS max_threads = 1, max_block_size = 5) = (SELECT arraySort(groupArray((number, concat('{"d":', multiIf(number % 4 = 0, toString(number), number % 4 = 1, concat('"s', toString(number), '"'), number % 4 = 2, concat('[', toString(number), ']'), 'true'), ',"e":', toString(number), '}')))) FROM numbers(24));
CHECK TABLE c_cn SETTINGS check_query_single_value_result = 1;
DROP TABLE c_cn;
SELECT '-- ReplacingMergeTree with FINAL, with and without functions to subcolumns';
DROP TABLE IF EXISTS r; CREATE TABLE r (x UInt64, ver UInt64, json JSON(SHARED a UInt64, SHARED b String, SHARED c Array(UInt8))) ENGINE = ReplacingMergeTree(ver) ORDER BY x SETTINGS min_bytes_for_wide_part = 0, min_rows_for_wide_part = 0, index_granularity = 4, min_compress_block_size = 1;
INSERT INTO r SELECT number, 1, concat('{"a":', toString(number * 10), ',"b":"', repeat('x', number % 7), '","c":', toString(range(number % 4)), if(number % 2 = 0, concat(',"d":', toString(number)), ''), '}') FROM numbers(40); INSERT INTO r SELECT number, 2, concat('{"a":', toString(number * 10 + 1), ',"b":"v2","c":[9]}') FROM numbers(0, 40, 2);
SELECT 'r FINAL optimize_functions_to_subcolumns = 0', count(), sum(json.a), sum(length(json.c)), countIf(json.b = 'v2'), sum(json.c.size0) FROM r FINAL SETTINGS max_threads = 1, optimize_functions_to_subcolumns = 0;
SELECT 'r FINAL whole optimize_functions_to_subcolumns = 0', (SELECT arraySort(groupArray((x, toString(json)))) FROM r FINAL SETTINGS max_threads = 1, optimize_functions_to_subcolumns = 0) = (SELECT arraySort(groupArray((number, if(number % 2 = 0, concat('{"a":', toString(number * 10 + 1), ',"b":"v2","c":[9]}'), concat('{"a":', toString(number * 10), ',"b":"', repeat('x', number % 7), '","c":', toString(range(number % 4)), if(number % 2 = 0, concat(',"d":', toString(number)), ''), '}'))))) FROM numbers(40));
SELECT 'r FINAL optimize_functions_to_subcolumns = 1', count(), sum(json.a), sum(length(json.c)), countIf(json.b = 'v2'), sum(json.c.size0) FROM r FINAL SETTINGS max_threads = 1, optimize_functions_to_subcolumns = 1;
SELECT 'r FINAL whole optimize_functions_to_subcolumns = 1', (SELECT arraySort(groupArray((x, toString(json)))) FROM r FINAL SETTINGS max_threads = 1, optimize_functions_to_subcolumns = 1) = (SELECT arraySort(groupArray((number, if(number % 2 = 0, concat('{"a":', toString(number * 10 + 1), ',"b":"v2","c":[9]}'), concat('{"a":', toString(number * 10), ',"b":"', repeat('x', number % 7), '","c":', toString(range(number % 4)), if(number % 2 = 0, concat(',"d":', toString(number)), ''), '}'))))) FROM numbers(40));
DROP TABLE r;
SELECT '-- a Compact and a Wide part merged into a Wide one';
DROP TABLE IF EXISTS mx; CREATE TABLE mx (x UInt64, y UInt64, json JSON(SHARED a UInt64, SHARED b String, SHARED c Array(UInt8))) ENGINE = MergeTree ORDER BY x SETTINGS min_bytes_for_wide_part = 0, min_rows_for_wide_part = 20, index_granularity = 4, min_compress_block_size = 1, merge_max_block_size = 5;
INSERT INTO mx SELECT number, number, concat('{"a":', toString(number * 10), ',"b":"', repeat('x', number % 7), '","c":', toString(range(number % 4)), if(number % 2 = 0, concat(',"d":', toString(number)), ''), '}') FROM numbers(10); INSERT INTO mx SELECT number, number, concat('{"a":', toString(number * 10), ',"b":"', repeat('x', number % 7), '","c":', toString(range(number % 4)), if(number % 2 = 0, concat(',"d":', toString(number)), ''), '}') FROM numbers(10, 30);
SELECT 'mx parts before', groupArray(part_type) FROM (SELECT part_type FROM system.parts WHERE database = currentDatabase() AND table = 'mx' AND active ORDER BY name);
SELECT 'mx [json]', (SELECT arraySort(groupArray((x, toString(json)))) FROM mx  SETTINGS max_threads = 1) = (SELECT arraySort(groupArray((x, toString(json)))) FROM mem );
SELECT 'mx [(json.a, json)]', (SELECT arraySort(groupArray((x, toString((json.a, json))))) FROM mx  SETTINGS max_threads = 1) = (SELECT arraySort(groupArray((x, toString((json.a, json))))) FROM mem );
OPTIMIZE TABLE mx FINAL;
SELECT 'mx parts after', groupArray(part_type) FROM (SELECT part_type FROM system.parts WHERE database = currentDatabase() AND table = 'mx' AND active ORDER BY name);
SELECT 'mx [json]', (SELECT arraySort(groupArray((x, toString(json)))) FROM mx  SETTINGS max_threads = 1) = (SELECT arraySort(groupArray((x, toString(json)))) FROM mem );
SELECT 'mx [(json.c.size0, json.b)]', (SELECT arraySort(groupArray((x, toString((json.c.size0, json.b))))) FROM mx  SETTINGS max_threads = 1) = (SELECT arraySort(groupArray((x, toString((json.c.size0, json.b))))) FROM mem );
CHECK TABLE mx SETTINGS check_query_single_value_result = 1;
DROP TABLE mx;
SELECT '-- a materialized view parsing a String source into a SHARED target';
DROP TABLE IF EXISTS src; DROP TABLE IF EXISTS dst; DROP VIEW IF EXISTS mv;
CREATE TABLE src (x UInt64, s String) ENGINE = MergeTree ORDER BY x;
CREATE TABLE dst (x UInt64, y UInt64, json JSON(SHARED a UInt64, SHARED b String, SHARED c Array(UInt8))) ENGINE = MergeTree ORDER BY x SETTINGS min_bytes_for_wide_part = 0, min_rows_for_wide_part = 0, index_granularity = 4, min_compress_block_size = 1;
CREATE MATERIALIZED VIEW mv TO dst AS SELECT x, x AS y, CAST(s, 'JSON(SHARED a UInt64, SHARED b String, SHARED c Array(UInt8))') AS json FROM src;
INSERT INTO src SELECT number, concat('{"a":', toString(number * 10), ',"b":"', repeat('x', number % 7), '","c":', toString(range(number % 4)), if(number % 2 = 0, concat(',"d":', toString(number)), ''), '}') FROM numbers(40);
SELECT 'dst [json]', (SELECT arraySort(groupArray((x, toString(json)))) FROM dst  SETTINGS max_threads = 1) = (SELECT arraySort(groupArray((x, toString(json)))) FROM mem );
SELECT 'dst [(json.a, json.c.size0)]', (SELECT arraySort(groupArray((x, toString((json.a, json.c.size0))))) FROM dst  SETTINGS max_threads = 1) = (SELECT arraySort(groupArray((x, toString((json.a, json.c.size0))))) FROM mem );
DROP VIEW mv; DROP TABLE src; DROP TABLE dst;
SELECT '-- a projection holding the whole column, and a lightweight update through patch parts';
DROP TABLE IF EXISTS pr; CREATE TABLE pr (x UInt64, y UInt64, json JSON(SHARED a UInt64, SHARED b String, SHARED c Array(UInt8)), PROJECTION p (SELECT y, json ORDER BY y)) ENGINE = MergeTree ORDER BY x SETTINGS min_bytes_for_wide_part = 0, min_rows_for_wide_part = 0, index_granularity = 4, min_compress_block_size = 1, enable_block_number_column = 1, enable_block_offset_column = 1;
INSERT INTO pr SELECT number, number % 5, concat('{"a":', toString(number * 10), ',"b":"', repeat('x', number % 7), '","c":', toString(range(number % 4)), if(number % 2 = 0, concat(',"d":', toString(number)), ''), '}') FROM numbers(40);
SELECT 'pr by y', count(), sum(json.a) FROM pr WHERE y = 3 SETTINGS max_threads = 1, optimize_use_projections = 1, force_optimize_projection = 1;
SELECT 'pr projection used', count() > 0 FROM (EXPLAIN indexes = 1 SELECT count(), sum(json.a) FROM pr WHERE y = 3 SETTINGS optimize_use_projections = 1) WHERE explain LIKE '%ReadFromMergeTree (p)%';
OPTIMIZE TABLE pr FINAL;
SELECT 'pr by y after optimize', count(), sum(json.a) FROM pr WHERE y = 3 SETTINGS max_threads = 1, optimize_use_projections = 1, force_optimize_projection = 1;
ALTER TABLE mem UPDATE y = y % 5 WHERE 1;
SELECT 'pr [(y, json)]', (SELECT arraySort(groupArray((x, toString((y, json))))) FROM pr  SETTINGS max_threads = 1) = (SELECT arraySort(groupArray((x, toString((y, json))))) FROM mem );
UPDATE pr SET json = CAST('{"a":1000,"b":"upd","c":[7]}', 'JSON(SHARED a UInt64, SHARED b String, SHARED c Array(UInt8))') WHERE x = 7;
SELECT 'pr lightweight update', json, json.a, json.b, json.c.size0 FROM pr WHERE x = 7;
SELECT 'pr patch parts', count() FROM system.parts WHERE database = currentDatabase() AND table = 'pr' AND active AND name LIKE 'patch%';
SELECT 'pr sum after update', sum(json.a), count() FROM pr SETTINGS max_threads = 1;
ALTER TABLE pr APPLY PATCHES SETTINGS mutations_sync = 2;
SELECT 'pr sum after apply', sum(json.a), count(), (SELECT json FROM pr WHERE x = 7) FROM pr SETTINGS max_threads = 1;
CHECK TABLE pr SETTINGS check_query_single_value_result = 1;
DROP TABLE pr; DROP TABLE mem;
